{
  "requirements": [
    {
      "id": "F-01",
      "text": "The system shall ensure that no account can have a negative balance and shall prevent overdrafts.",
      "quality_axes": ["Safety|Trustworthiness|Responsibility"],
      "derived_from": ["SAF-01", "TRU-04"],
      "kaos_level": "strategic",
      "parent": null
    },
    {
      "id": "F-02",
      "text": "The system shall automatically withdraw funds from the related saving account only when sufficient funds are available.",
      "quality_axes": ["Safety|Efficiency"],
      "derived_from": ["SAF-02", "RES-05"],
      "kaos_level": "tactical",
      "parent": null
    },
    {
      "id": "F-03",
      "text": "The system shall inform the user and terminate the transaction if the saving account balance is insufficient for the withdrawal.",
      "quality_axes": ["Safety"],
      "derived_from": ["SAF-03"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-04",
      "text": "The system shall log all transactions with date, time, type, amount, and resulting balance.",
      "quality_axes": ["Safety|Trustworthiness"],
      "derived_from": ["SAF-04", "TRU-03"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-05",
      "text": "The system shall implement secure PIN verification for user authentication.",
      "quality_axes": ["Safety|Trustworthiness|Responsibility"],
      "derived_from": ["SAF-05", "TRU-02", "RES-04"],
      "kaos_level": "tactical",
      "parent": null
    },
    {
      "id": "F-06",
      "text": "The system shall provide immediate feedback while notifying users of insufficient funds.",
      "quality_axes": ["Efficiency|Safety|Trustworthiness"],
      "derived_from": ["EFF-06", "RES-06", "TRU-06"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-07",
      "text": "The ATM system shall process transactions within 3 seconds while optimizing for energy efficiency.",
      "quality_axes": ["Efficiency|Sustainability"],
      "derived_from": ["EFF-01", "GRN-01"],
      "kaos_level": "tactical",
      "parent": null
    },
    {
      "id": "F-08",
      "text": "The ATM system shall maintain a transaction throughput of at least 100 transactions per minute.",
      "quality_axes": ["Efficiency"],
      "derived_from": ["EFF-02"],
      "kaos_level": "tactical",
      "parent": null
    },
    {
      "id": "F-09",
      "text": "The ATM application shall optimize data retrieval to minimize latency when accessing transaction history.",
      "quality_axes": ["Efficiency"],
      "derived_from": ["EFF-03"],
      "kaos_level": "tactical",
      "parent": null
    },
    {
      "id": "F-10",
      "text": "The ATM system shall utilize energy-efficient hardware components to operate.",
      "quality_axes": ["Sustainability"],
      "derived_from": ["GRN-03"],
      "kaos_level": "tactical",
      "parent": null
    },
    {
      "id": "F-11",
      "text": "The ATM system shall provide an option for clients to receive electronic transaction records instead of paper receipts.",
      "quality_axes": ["Sustainability"],
      "derived_from": ["GRN-05"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-12",
      "text": "The ATM system shall ensure all transactions comply with applicable financial regulations and standards.",
      "quality_axes": ["Responsibility"],
      "derived_from": ["RES-01"],
      "kaos_level": "strategic",
      "parent": null
    },
    {
      "id": "F-13",
      "text": "The ATM system shall maintain user privacy by securely encrypting all personal and financial data.",
      "quality_axes": ["Trustworthiness|Responsibility"],
      "derived_from": ["TRU-01", "RES-07"],
      "kaos_level": "strategic",
      "parent": null
    }
  ],
  "conflict_resolutions": [
    {
      "ids": ["SAF-01", "TRU-04"],
      "outcome": "merged",
      "favored_agent": null,
      "rationale": "Both requirements prevent negative balances, so they were merged for clarity."
    },
    {
      "ids": ["EFF-06", "RES-06"],
      "outcome": "merged",
      "favored_agent": null,
      "rationale": "Immediate feedback and notifications were combined to enhance user experience without compromising safety."
    },
    {
      "ids": ["EFF-01", "GRN-01"],
      "outcome": "merged",
      "favored_agent": null,
      "rationale": "Transaction processing optimization for energy efficiency was integrated with performance requirements."
    }
  ],
  "dropped": [
