      "id": "SAF-06",
      "reason": "The requirement for safe degradation during maintenance was not prioritized in the final model."
    },
    {
      "id": "SAF-07",
      "reason": "The requirement for a clear summary of account status after each transaction was not included in the final model."
    },
    {
      "id": "EFF-04",
      "reason": "This requirement was merged into F-01 to streamline negative balance prevention."
    },
