    },
    {
      "id": "GRN-06",
      "reason": "The requirement for automatic shutdown during inactivity was not prioritized in the final model."
    },
    {
      "id": "GRN-07",
      "reason": "Annual assessments of environmental impact were not included in the final model."
    },
    {
      "id": "TRU-05",
      "reason": "The requirement for secure transaction history review was not included in the final model."
    },
    {
      "id": "TRU-07",
      "reason": "Data integrity validation was not included in the final model."
    },
    {
      "id": "RES-02",
      "reason": "Comprehensive transaction logs were integrated into F-04."
    },
    {
      "id": "RES-03",
      "reason": "Preventing negative balances was merged into F-01."
    },
    {
      "id": "RES-05",
      "reason": "Automatic fund withdrawal was integrated into F-02."
    },
    {
      "id": "RES-06",
      "reason": "Immediate notifications were merged into F-06."
    },
    {
      "id": "RES-07",
      "reason": "User privacy maintenance was integrated into F-13."
    }
  ],
